    $u34e305ea${"format":"udebt-analysis","version":1,"contract":1,"repo":"sentry-javascript","url":"https://github.com/getsentry/sentry-javascript","rev":"6bee2f2ccccdac123199d1b610c70a3bad5c8194","sha":"6bee2f2ccccdac123199d1b610c70a3bad5c8194","generated_at":"2026-11-15T09:56:46+00:00","seconds":526.9,"limits":{"max_commits":20000,"max_mb":500,"clone_timeout":900},"clone_bytes":300482560,"map_source":"llm","llm_calls":15,"code_excerpts":false,"counts":{"commits":17695,"contributors":851,"units":15,"walkthroughs":12,"tour":true},"files":{"weights.json":4375315,"structure.json":93959,"history.json":35303,"contributors.json":251392,"map.json":40529,"specs.json":89114},"note":null,"public":true}$u34e305ea$::jsonb,
