kages/browser/src/sdk.ts","packages/browser/src/integrations","packages/browser/src/profiling"],"centrality":4,"scope":"architectural","history":[],"importance":0.344},{"id":"browser-sdk/tracing","name":"Browser tracing and web vitals","kind":"module","summary":"browserTracingIntegration, request spans and web-vitals/performance spans.","decision":"Spans emitted from PerformanceObserver entries in browser-utils.","paths":["packages/browser/src/tracing","packages/browser-utils/src"],"centrality":4,"scope":"architectural","history":[],"importance":0.275},{"id":"browser-sdk/bundles","name":"CDN bundles and shims","kind":"module","summary":"Bundle entry points and shims for absent integrations.","decision":"Separate index.bundle.* variants built with rollup.","paths":["packages/browser/rollup.bundle.config.mjs","packages/integration-shims","packages/browser/src/index.bundle.tracing.replay.ts"],"centrality":3,"scope":"architectural","history":[],"importance":0.161}]},{"id":"node-sdk","name":"Node SDK and server-utils instrumentation","kind":"module","summary":"Node init, HTTP/fetch instrumentation, process-level integrations, and shared server-runtime integrations in server-utils reused by Bun, Deno, Cloudflare and others.","decision":"Move database/AI/framework instrumentations out of @sentry/node into runtime-agnostic @sentry/server-utils using diagnostics-channel subscribers.","alternatives":"Keep OTel-instrumentation-per-library inside @sentry/node.","why":"Reuse across runtimes; recent exports consolidation commit.","paths":["packages/node/src","packages/server-utils/src","packages/bun/src","packages/deno/src","packages/vercel-edge/src"],"centrality":5,"clusters":["C2.1","C2.3","C2.5","C2.7","C4.3","C5","C23"],"scope":"architectural","history":[{"sha":"897f5a2","date":"2026-08-24","klass":"human","agent":null,"author":"Francesco Gringl-Novy","subject":"ref(server-utils): Export integrations from `@sentry/server-utils` & remove `/orchestrion` entrypoint (#23459)"}],"importance":0.903,"orientation":{"purpose":"The Node SDK covers init, HTTP/fetch instrumentation and process-level integrations. A runtime-agnostic server-utils package holds the integrations shared by Bun, Deno, Cloudflare and others.","decision":"Database, AI and framework instrumentations move out of @sentry/node into @sentry/server-utils, using diagnostics-channel subscribers. Keeping per-library OTel instrumentation inside @sentry/node was the alternative. The reason is reuse across runtimes.","where":[{"path":"packages/node/src","what":"Node init and integrations"},{"path":"packages/server-utils/src","what":"shared server integrations"},{"path":"packages/bun/src","what":"a runtime SDK reusing them"}],"shaped_by":"Francesco Gringl-Novy, a human working alone, consolidated the server-utils integration exports in August 2026 [human].","basis":"c953cc456913","head":"6bee2f2ccccdac123199d1b610c70a3bad5c8194","generated_at":"2026-11-15T09:50:47+00:00"}},{"id":"otel-bridge","name":"OpenTelemetry bridge","kind":"boundary","summary":"Adapter making Sentry scopes, spans, sampling and propagation run on OpenTelemetry.","decision":"Node-family SDKs delegate span/context management to OpenTelemetry via custom propagator, sampler and async context strategy.","alternatives":"Own tracing implementation on Node.","why":"Reuse of the OTel ecosystem of instrumentations (switched in 2024 for sveltekit/node).","paths":["packages/opentelemetry/src","packages/node/src/sdk"],"centrality":4,"clusters":["C1.4","C2.5"],"scope":"architectural","history":[{"sha":"b0e1db0","date":"2024-03-15","klass":"human","agent":null,"author":"Lukas Stracke","subject":"feat(sveltekit): Switch to Otel-based `@sentry/node` package (#11075)"}],"importance":0.525,"orientation":{"purpose":"Adapts Sentry scopes, spans, sampling and propagation so they run on top of OpenTelemetry.","decision":"Node-family SDKs delegate span and context management to OpenTelemetry through a custom propagator, sampler and async-context strategy. Sentry's own Node tracing was not kept. The reason is reuse of the OTel instrumentation ecosystem.","where":[{"path":"packages/opentelemetry/src","what":"propagator, sampler, context strategy"},{"path":"packages/node/src/sdk","what":"Node wiring of OTel"}],"shaped_by":"Lukas Stracke, a human working alone, switched sveltekit to the OTel-based @sentry/node in March 2024 [human].","basis":"2d19af152680","head":"6bee2f2ccccdac123199d1b610c70a3bad5c8194","generated_at":"2026-11-15T09:50:47+00:00"}},{"id":"orchestrion","name":"Orchestrion code-transform instrumentation","kind":"decision","summary":"Build-time and load-time code transformation injects tracing channels into third-party libraries.","decision":"Use orchestrion-style AST transforms (bundler plugins, ESM loader hooks, runtime injection package) with per-library config to publish tracing channels instead of monkey-patching.","alternatives":"Runtime monkey-patching via require-in-the-middle/OTel instrumentation.","why":"Works with ESM and bundlers; AI-agent-assisted split into a dedicated package.","paths":["packages/server-utils/src/orchestrion","packages/server-runtime-injection","packages/server-utils/src/tracing-channel.ts"],"centrality":4,"clusters":["C4","C4.2"],"scope":"architectural","history":[{"sha":"8c2ab94","date":"2026-09-01","klass":"assisted","agent":"claude-code","author":"Francesco Gringl-Novy","subject":"feat(server-runtime-injection): Split runtime orchestrion injection into a dedicated package (#23685)"},{"sha":"897f5a2","date":"2026-08-24","klass":"human","agent":null,"author":"Francesco Gringl-Novy","subject":"ref(server-utils): Export integrations from `@sentry/server-utils` & remove `/orchestrion` entrypoint (#23459)"}],"importance":0.499,"orientation":{"purpose":"Instruments third-party libraries by transforming their code at build or load time so they publish tracing channels.","decision":"AST transforms (bundler plugins, ESM loader hooks, a runtime injection package)